use sha2::{Digest, Sha256};
#[path = "../workspace_graph/identity_resolution/base/cache_billing/main7f8_reader.rs"]
mod reader;
const PATH: &str = "docs/evidence/main7f8-source-fronts-20261017/inputs.json";
