    };
    let seed = tail.as_ref().clone();
    let mut nested = seed.clone();
    for _ in 0..crate::cache_codec::MAX_DEPTH + 2 {
        let mut parent = seed.clone();
        parent.kind = K::Unary {
            op: crate::ast::UnaryOp::Neg,
            value: Box::new(nested),
        };
        nested = parent;
    }
